use std::sync::{Arc, Mutex};
use std::thread;
fn require_send_sync<T: Send + Sync>() {}
fn main() {
    require_send_sync::<u32>();
    let shared = Arc::new(Mutex::new(0));
    let worker_shared = Arc::clone(&shared);
    let worker = thread::spawn(move || {
        if let Ok(mut value) = worker_shared.lock() { *value += 1; }
    });
    if worker.join().is_err() { println!("worker failed"); return; }
    match shared.lock() {
        Ok(value) => println!("{value}"),
        Err(_) => println!("lock poisoned"),
    };
}

use std::thread;
fn main() {
    let message = String::from("message from worker");
    let worker = thread::spawn(move || message);
    match worker.join() {
        Ok(message) => println!("{message}"),
        Err(_) => println!("worker panicked"),
    };
}
